-- aar/w3/aar_row_595_draft1.sql
-- DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3. For a W1 grade, then insert from seat 36.
-- One ask_aar_snapshots row for ASK 595 and its ask_aar_builders row.
-- READ BY W3 FOR THIS ROW: Wall 11452, 11453, 11456, 11483, 11485 in full (by SQL); audit_log 41329; ask590/w4/fix1500/notes595.md in full; md5sum by W3 on every file named.
-- NOT READ BY W3: the card and the press in W4's thread (the press words are as Wall 11483 gives them); the n8n workflows; W1's grade file.
-- md5_written: 44d727af (engine target) and 73f7b6e2 (child target). W1's Wall 11456 says its rebuild equals both targets and does not print the md5s. W1 CONFIRMS THEM WHEN IT GRADES THIS ROW.
-- The operator's 01:32 CST message has no md_notes_rulings row; W3 quotes it as received in the W3 thread.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (595, '1', $t$ASK 595: the E-REVCLOSE item keeps the judge's line whole (the 1,500-character cut added by ASK 590 removed)$t$,
  $t$No judge line is cut where it is stored or shown in the E-REVCLOSE item: the one 1,500-character cut that the ASK 590 write added to a stored flagged_line is removed, so that ASK 587 item A stands on the live engine. (W1's grade, Wall 11456: "This removes the one cut that ASK 590 added to a stored flagged_line"; W1's read, Wall 11452.)$t$,
  'in part',
  $t$Written by W4 on the operator's press "Write 595, then the other three" at 01:58 CST 2026-11-24, with no debate run live (Wall 11483; audit 41329). Engine moMxiV4Irg1uRBZN d819ff4c to 6e0c5013-ea43-4aab-aa2e-7debf1bdbb3a; child MqQHRl7mQQ0z8QdT 31329164 to e7f13f7e-2d3a-44d6-ad32-fd12358f8a5f. One change, in the Shared Library of each, library line 3564: out.push({r,line:l.slice(0,1500),hit}) becomes out.push({r,line:l,hit}). No other node changes. LIB 0e45d9fe625d140d, MAP ccda7f6937ff007a. What is live: a judge line that quotes a reversed close sentence is recorded whole by the matcher rev590Hits, and Send Back Build, Alt Send Back Build and the child's R2 Alt Send Back Build store it whole as flagged_line and response_line of the E-REVCLOSE item. How it was found: the operator asked at 01:32 CST what had become of the 1,500 fix; W3 had not verified ASK 587 on the live engine and asked W1 to read it; W1 found items B, C1, C2, D and E standing verbatim and item A standing for every line ASK 587 covered, with this one new cut added by ASK 590 (Wall 11452). W1's mistake (it graded the 590 build, the re-cut and the write without checking them against 587 A) and W4's (it carried the cut into the matcher; the rule was not in its 590 tests) are stated in Wall 11452 and 11453. W3's: the 590 plan did not name ASK 587 item A as a check. The path: W1's read (Wall 11452); build rev 0 (Wall 11453); W1 PASS (Wall 11456); the press; the write (Wall 11483); W1 readback MATCH (Wall 11485). IN PART, because no run has executed on 6e0c5013 or a later version: the whole line is shown by tfix (a line of 2,832 characters) and the readback, not by a run. NOT IN THIS WRITE (scope rule; W1's rulings in Wall 11456), found by W4's scan and W1's read: a DROPPED question-round reply is stored cut to 2,000 characters in odv1_question_round_log; the reversed close sentences are shown to the judges cut to 500 characters and in the send-back text to 400; error messages are cut to 300 (W1: leave them). W4 built the first three and a fourth (the library line 2277 reader, 1,500) as a follow-on (Wall 11487), W1 PASS with R1 (Wall 11490); not written at the draft of this row. The 23 other cuts at 1,500 on response_line and record fields stood before ASK 587 and are ASK 597's subject. Consequence: ASK 596 (the standing test set) and rule 3 of the coding standard (ASK 599) were ordered from this defect.$t$,
  '11452, 11453, 11456, 11483, 11485',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$01:32 CST 2026-11-24, W3 thread: "I was supposed to be fixing a few of the major critical things in the 1500, and it seemed like you guys been doing everything other than that." (No md_notes_rulings row holds this message; it is quoted as W3 received it.) His press at 01:58 CST 2026-11-24 in W4's thread: "Write 595, then the other three" (as Wall 11483 gives it).$t$::text),
  $j${"answer": "Write 595, then the other three", "source": "Wall 11483; audit 41329", "thread": "W4", "press_time": "01:58 CST 2026-11-24", "question": "not in the record W3 read (the card is in W4's thread)"}$j$::jsonb,
  'W4',
  $j${"md5": "a4321176", "path": "ask590/w4/fix1500/notes595.md", "commit": "not stated in the Wall posts W3 read", "note": "build notes rev 0; no separate plan: the defect and its one-line fix were stated by W1 (Wall 11452)", "source": "md5sum by W3; Wall 11453, 11456"}$j$::jsonb,
  $j$[{"md5": "44d727af", "path": "ask590/w4/fix1500/target_engine_fix.json", "note": "the engine target on live d819ff4c; graded, written and read back", "source": "md5sum by W3; Wall 11456, 11485"}, {"md5": "73f7b6e2", "path": "ask590/w4/fix1500/target_child_fix.json", "note": "the child target on live 31329164", "source": "md5sum by W3; Wall 11456, 11485"}, {"md5": "a4321176", "path": "ask590/w4/fix1500/notes595.md", "note": "build notes rev 0", "source": "md5sum by W3"}, {"md5": "c10ac750", "path": "ask590/w4/fix1500/buildfix.cjs", "note": "the build script", "source": "md5sum by W3"}, {"md5": "e5cdd5ed", "path": "ask590/w4/fix1500/tfix.cjs", "note": "the test, 8 cases", "source": "md5sum by W3"}, {"md5": "8779ad1f", "path": "ask590/w4/fix1500/out_tfix.txt", "note": "test output; the same md5 as write/tfix_at_write.txt", "source": "md5sum by W3"}, {"md5": "10b2bcc8", "path": "ask590/w4/fix1500/write/prewrite_eng595.json", "note": "fresh fetch before the write; the same md5 as ASK 590's fetchback_eng590.json", "source": "md5sum by W3"}, {"md5": "26a0a881", "path": "ask590/w4/fix1500/write/prewrite_child595.json", "note": "fresh fetch before the write, child", "source": "md5sum by W3"}, {"md5": "7ccf5572", "path": "ask590/w4/fix1500/write/put_eng595.json", "note": "PUT body, engine", "source": "md5sum by W3"}, {"md5": "5f0f8864", "path": "ask590/w4/fix1500/write/put_child595.json", "note": "PUT body, child", "source": "md5sum by W3"}, {"md5": "1987f2eb", "path": "ask590/w4/fix1500/write/fetchback_eng595.json", "note": "fetch-back after the write", "source": "md5sum by W3"}, {"md5": "2dabe69f", "path": "ask590/w4/fix1500/write/fetchback_child595.json", "note": "fetch-back after the write, child", "source": "md5sum by W3"}, {"md5": "d70909f5", "path": "ask590/w4/fix1500/write/write595.sh", "note": "the write script", "source": "md5sum by W3"}]$j$::jsonb,
  $j${"copy": "restore the engine and the child together from ask590/w4/fix1500/write/revert_eng595.json 2c766aca and revert_child595.json 825398a7 (to d819ff4c and 31329164). A revert now would also undo 586 J1 and 586 J6, written on top, and would restore the cut.", "path": "ask590/w4/fix1500/write/revert_eng595.json; ask590/w4/fix1500/write/revert_child595.json", "source": "audit 41329; md5sum by W3 (the two files have the md5s of ASK 590's PUT bodies); the last sentence is W3's reading of the chain in Wall 11485"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS (build rev 0: W1's rebuild equals both targets, 0 node differences; only library line 3564 changes, 14 characters shorter in engine and child; no slice(0,1500) left in it; tfix 8 PASS rerun by W1; Library pair PASSES)", "wall_id": 11456, "md5_graded": "44d727af", "verdict_norm": "PASS", "source": "Wall 11456 \"Checked\"; the md5 is md5sum by W3 on ask590/w4/fix1500/target_engine_fix.json; W1's post does not print it"}, {"seat": "W1", "verdict": "PASS (the child target, the same grade)", "wall_id": 11456, "md5_graded": "73f7b6e2", "verdict_norm": "PASS", "source": "Wall 11456; md5sum by W3 on ask590/w4/fix1500/target_child_fix.json"}]$j$::jsonb,
  ARRAY['44d727af','73f7b6e2'], '[41329]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN", "before": "d819ff4c, 422 nodes", "after": "6e0c5013-ea43-4aab-aa2e-7debf1bdbb3a"}, {"kind": "n8n workflow", "name": "child MqQHRl7mQQ0z8QdT", "before": "31329164, 156 nodes", "after": "e7f13f7e-2d3a-44d6-ad32-fd12358f8a5f"}, {"kind": "library line", "name": "Shared Library line 3564 (rev590Hits), engine and child", "before": "out.push({r,line:l.slice(0,1500),hit});", "after": "out.push({r,line:l,hit});"}, {"kind": "library", "name": "Shared Library, engine and child", "before": "LIB 8ebbd11e9443b540, MAP 3ae647f38b5b74ac", "after": "LIB 0e45d9fe625d140d, MAP ccda7f6937ff007a"}]$j$::jsonb,
  $j$[{"name": "tfix.cjs, 8 cases", "result": "8 PASS at the build, at W1's rerun and at the write: only library line 3564 changes; no 1500 cut left in it; a judge line of 2,832 characters reaches flagged_line and response_line whole, engine and child; control: the live library cut the same line to 1,500", "source": "Wall 11453 item 2; 11456; 11483 item 1; notes595.md section 3"}, {"name": "Library Check pair", "result": "PASSES: LIB 0e45d9fe625d140d, MAP ccda7f6937ff007a", "source": "Wall 11456; 11485 item 1"}, {"name": "Scan of every library line and node changed since the ASK 587 write", "result": "no other 1,500 cut; four other kinds of cut found and listed, not changed", "source": "Wall 11453 item 3; notes595.md section 4"}]$j$::jsonb,
  $j$[{"seat": "W1", "wall_id": 11485, "result": "MATCH (fresh fetch from n8n history: 6e0c5013 and e7f13f7e, 0 differences to W4's target and 0 to W1's own rebuild; from the base only library line 3564; Library Check PASS)"}]$j$::jsonb,
  $j${"case": "UNEXERCISED. No run has executed on 6e0c5013 or a later version (debate_results last row 03:57 UTC 2026-11-24; Wall 11485). EXPECT on the first run that holds an E-REVCLOSE item on a judge line over 1,500 characters: flagged_line and response_line of that debate_enforcer_log row equal the judge's whole line.", "source": "Wall 11483, 11485; notes595.md; the EXPECT is W3's reading"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "not yet at the draft of this row: version 287 (9f39e989). W3's entries for ASK 590, 595, 586 J1 and 586 J6 are manual1123/w3/a590_595_586/em_pairs_590_595_586_draft2.json b3ed7178 (8 parts, 11 pairs), W1 PASS (Wall 11488, 11491), on the operator's card, not pressed at the draft of this row"}$j$::jsonb,
  'read back', $j$[11452, 11453, 11456, 11483, 11485]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "built and wrote ASK 595 on its card", "wall_id": 11483}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
